sed -i '/import androidx.compose.runtime.collectAsState/a import androidx.compose.runtime.DisposableEffect\nimport androidx.compose.runtime.LaunchedEffect' app/src/main/java/com/example/MainActivity.kt

sed -i '/fun MainScreen(/a \    val callManager = remember(userId) { ActiveCallManager(userId) }\n    val incomingCall by callManager.incomingCall.collectAsState()\n\n    DisposableEffect(userId) {\n        callManager.startListening()\n        onDispose { callManager.stopListening() }\n    }\n\n    incomingCall?.let { call ->\n        IncomingCallDialog(\n            call = call,\n            onAccept = {\n                callManager.acceptCall(call.id)\n                navController.navigate("callScreen/${call.channelId}/${call.isVideoCall}")\n            },\n            onReject = {\n                callManager.rejectCall(call.id)\n            }\n        )\n    }' app/src/main/java/com/example/MainActivity.kt

sed -i 's/val channelId = "call_" + minOf(userId, targetUserId) + "_" + maxOf(userId, targetUserId)/val channelId = "call_" + minOf(userId, targetUserId) + "_" + maxOf(userId, targetUserId)\n                        callManager.initiateCall(userName, targetUserId, otherUserName, isVideo, channelId)/' app/src/main/java/com/example/MainActivity.kt
